        _updateBriefing(state) {
            var round = Math.min(Math.max((state && state.currentPeriod) || 1, 1), 4);
            var cfg = ROUND_CONFIG[round];
            if (!cfg) return;

            var t = function(k) {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    return window.mySimulation.t(k);
                }
                return k;
            };

            var roundWord = (t('round_label') || 'Round');
            var tagEl = document.getElementById('roundTag');
            if (tagEl) tagEl.textContent = roundWord.toUpperCase() + ' ' + round;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.setAttribute('data-i18n', cfg.titleKey);
                titleEl.textContent = t(cfg.titleKey);
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.setAttribute('data-i18n', cfg.briefKey);
                briefEl.textContent = t(cfg.briefKey);
            }

            var primaryLabelEl = document.getElementById('primaryLabel');
            if (primaryLabelEl) {
                primaryLabelEl.setAttribute('data-i18n', cfg.primaryLabel);
                primaryLabelEl.textContent = t(cfg.primaryLabel);
            }

            var secondaryLabelEl = document.getElementById('secondaryLabel');
            if (secondaryLabelEl) {
                secondaryLabelEl.setAttribute('data-i18n', cfg.secondaryLabel);
                secondaryLabelEl.textContent = t(cfg.secondaryLabel);
            }

            var intensityLabelEl = document.getElementById('intensityLabel');
            if (intensityLabelEl) {
                intensityLabelEl.setAttribute('data-i18n', cfg.intensityLabel);
                intensityLabelEl.textContent = t(cfg.intensityLabel);
            }

            var primarySelect = document.getElementById('primaryChoice');
            if (primarySelect) {
                var prevPrimary = primarySelect.value;
                primarySelect.innerHTML = '';
                cfg.primaryOptions.forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt.v;
                    o.textContent = t(opt.k);
                    o.setAttribute('data-i18n', opt.k);
                    primarySelect.appendChild(o);
                });
                var validValues = cfg.primaryOptions.map(function(x) { return x.v; });
                if (validValues.indexOf(prevPrimary) !== -1) primarySelect.value = prevPrimary;
            }

            var secondarySelect = document.getElementById('secondaryChoice');
            if (secondarySelect) {
                var prevSecondary = secondarySelect.value;
                secondarySelect.innerHTML = '';
                cfg.secondaryOptions.forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt.v;
                    o.textContent = t(opt.k);
                    o.setAttribute('data-i18n', opt.k);
                    secondarySelect.appendChild(o);
                });
                var validSec = cfg.secondaryOptions.map(function(x) { return x.v; });
                if (validSec.indexOf(prevSecondary) !== -1) secondarySelect.value = prevSecondary;
            }

            this._lastRenderedPeriod = round;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new DistributionExplorerAdapter(), {
            simulationType: 'distribution_explorer',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

